primes = [0] * (10 ** 6 + 3)
primes[0] = 1
primes[1] = 1
for p in range(2, len(primes)):
	if primes[p] == 0:
		for j in range(2, len(primes)):
			k = j * p
			if k >= len(primes):
				break
			primes[k] = 1
P = [x for x in range(len(primes)) if primes[x] == 0]

def find_factorial_factor(N):
	dic = {}
	for p in P:
		if p > 10 ** 6:
			break
		if p > N:
			break
		temp = p
		count = 0
		while temp <= N:
			count += N // temp
			temp *= p
		dic[p] = count
	return dic

def find_factor(N):
	dic = {}
	for p in P:
		if N % p == 0:
			dic[p] = 1
		if p > 10 ** 6 + 1:
			break
	return dic

def find_ans(N, K):
	prime_K = find_factor(K)
	prime_N = find_factorial_factor(N)
	prime_want = [p for p in prime_N if p not in prime_K]
	ans = [(p, prime_N[p]) for p in prime_want]
	true_ans = 1
	MOD = 10 ** 9 + 7
	for (p, exp) in ans:
		true_ans *= pow(p, exp, MOD)
		true_ans %= MOD
	return true_ans
for _ in range(int(input())):
	(N, K) = list(map(int, input().strip().split()))
	print(find_ans(N, K))
